// ── shared styles injected into every shadow root ──
const BASE_CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400&family=Jost:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap');
  :host{display:flex;width:100%;height:100%;overflow:hidden}
  *{box-sizing:border-box;margin:0;padding:0;font-family:'Jost',sans-serif}
  .slide{width:100%;height:100%;overflow:hidden;background:#fdf8f2;color:#2c1a0e;display:flex}
  .serif{font-family:'Playfair Display',serif}
  .mono{font-family:'JetBrains Mono',monospace}
  .gold{color:#c9a46e}
  .cream{color:#fdf8f2}
  /* left accent strip */
  .left-strip{width:8px;height:100%;background:#2c1a0e;flex-shrink:0}
  /* slide header bar */
  .hdr-bar{background:#2c1a0e;padding:18px 36px;display:flex;align-items:center;gap:12px}
  .hdr-bar .title{font-family:'Playfair Display',serif;font-size:clamp(20px,2.8vw,34px);font-weight:700;color:#fdf8f2}
  .hdr-bar .line{flex:1;height:1px;background:rgba(201,164,110,.3)}
  .hdr-bar .badge{font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:#c9a46e}
  /* body area */
  .body{flex:1;padding:28px 36px;overflow:hidden;display:flex;flex-direction:column;gap:16px}
  /* two-col layout */
  .two-col{display:grid;grid-template-columns:1fr 1fr;gap:20px;flex:1}
  /* image frame */
  .img-frame{border-radius:10px;overflow:hidden;border:1px solid #e8e0d5;background:#f5f0e8;display:flex;align-items:center;justify-content:center}
  .img-frame img{width:100%;height:100%;object-fit:contain;display:block}
  /* card */
  .card{background:#fff;border-radius:10px;border:1px solid #e8e0d5;padding:16px 20px}
  /* code */
  .code{background:#1e1410;border-radius:8px;padding:14px 18px;font-family:'JetBrains Mono',monospace;font-size:clamp(10px,1.1vw,13px);color:#e8d5b0;line-height:1.7;border-left:3px solid #c9a46e}
  .kw{color:#fa8072}.fn{color:#c9a46e}.str{color:#98d8a0}.op{color:#88aacc}.cm{color:#888;font-style:italic}
  /* bullet */
  ul.bul{list-style:none;display:flex;flex-direction:column;gap:5px}
  ul.bul li{display:flex;align-items:baseline;gap:8px;font-size:clamp(11px,1.15vw,14px);line-height:1.5;color:#3a2a1a}
  ul.bul li::before{content:'';width:5px;height:5px;border-radius:50%;background:#c9a46e;flex-shrink:0;margin-top:5px}
  /* section slide */
  .sec-slide{background:#2c1a0e;color:#fdf8f2;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;padding:40px}
  .sec-big{font-family:'Playfair Display',serif;font-size:clamp(36px,6vw,80px);font-weight:700;color:#fdf8f2}
  .sec-sub{font-size:clamp(11px,1.4vw,16px);color:#c9a46e;letter-spacing:.14em;text-transform:uppercase;font-weight:500}
  /* tag */
  .tag{display:inline-flex;align-items:center;padding:4px 12px;border-radius:20px;font-size:clamp(10px,.9vw,12px);font-weight:600;letter-spacing:.04em}
  .tag-gold{background:#f5e8d0;color:#7a5020;border:1px solid #e8d5b0}
  .tag-green{background:#e8f5ee;color:#1a5c35;border:1px solid #a8d5b8}
  .tag-purple{background:#eeecf8;color:#3a2a7a;border:1px solid #c5bef0}
  /* smell card */
  .smell{display:grid;grid-template-columns:5px 150px 1fr;align-items:stretch;background:#fff;border-radius:10px;overflow:hidden;border:1px solid #e8e0d5}
  .smell-bar{background:var(--bar)}
  .smell-lbl{padding:16px 14px;font-family:'Playfair Display',serif;font-size:clamp(13px,1.4vw,18px);font-weight:700;color:#2c1a0e;display:flex;align-items:center;line-height:1.2}
  .smell-txt{padding:16px 14px;font-size:clamp(11px,1.1vw,14px);color:#4a3a2a;line-height:1.5;display:flex;align-items:center;border-left:1px solid #f0e8dc}
  /* numbering badge */
  .num-badge{width:32px;height:32px;border-radius:50%;background:#2c1a0e;color:#c9a46e;font-family:'JetBrains Mono',monospace;font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:center;flex-shrink:0}
  /* golden divider */
  .gold-line{height:1px;background:#e8d5b0;margin:4px 0}
`;

function define(tag, html) {
  class El extends HTMLElement {
    connectedCallback() {
      const s = this.attachShadow({ mode: "open" });
      s.innerHTML = `<style>${BASE_CSS}</style>${html}`;
    }
  }
  customElements.define(tag, El);
}

