// Helper for image slides
function imgSlide(tag, title, badge, images, layout = "single") {
  let inner;
  if (layout === "single") {
    inner = `<div class="img-frame" style="flex:1;border-radius:10px"><img src="${IMGS[images[0]]}" alt=""/></div>`;
  } else if (layout === "two") {
    inner = `<div class="two-col" style="flex:1;gap:16px">
      <div class="img-frame"><img src="${IMGS[images[0]]}" alt=""/></div>
      <div class="img-frame"><img src="${IMGS[images[1]]}" alt=""/></div>
    </div>`;
  } else if (layout === "three") {
    inner = `<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;flex:1">
      <div class="img-frame"><img src="${IMGS[images[0]]}" alt=""/></div>
      <div class="img-frame"><img src="${IMGS[images[1]]}" alt=""/></div>
      <div class="img-frame"><img src="${IMGS[images[2]]}" alt=""/></div>
    </div>`;
  }
  define(
    tag,
    `<div class="slide" style="flex-direction:column">
    <div class="hdr-bar"><span class="title">${title}</span><div class="line"></div><span class="badge">${badge}</span></div>
    <div class="body">${inner}</div>
  </div>`,
  );
}

